1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser } from "./auth";
6	import type { SslCertificate } from "@prisma/client";
7	
8	/**
9	 * Customer SSL certificate management — one-click Let's Encrypt certs for a
10	 * domain the customer has already pointed at their server. Ordering is
11	 * ownership-checked here (at enqueue time); the actual issue runs in the worker
12	 * (worker/ssl.ts, SSL_ISSUE) which SSHes to the box and runs certbot — or, in
13	 * SANDBOX/staging, simulates a successful issue. worker/ssl.ts's `sslSweep` then
14	 * owns renewal and reconciliation.
15	 */
16	
17	// Basic FQDN: one or more dot-separated labels + a 2–24 char alpha TLD. Rejects
18	// wildcards, protocols, ports and paths — certbot wants a bare hostname.
19	const FQDN_RE =
20	  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
21	
22	/**
23	 * Let's Encrypt rate-limit guard. MUST stay in sync with worker/ssl.ts — this
24	 * module cannot import it (worker/ssl.ts pulls in ssh2, which must never reach
25	 * the Next bundle), so the four values are duplicated deliberately.
26	 *
27	 * LE allows 5 duplicate certificates (identical hostname set) per week; blowing
28	 * through it locks the customer out of HTTPS for a full week. Every source of
29	 * attempts — this file's manual request/renew and the worker's automatic renewal
30	 * sweep — shares one counter, so they cannot add up to more than the limit
31	 * between them.
32	 *
33	 * Two caps, because they stop different things: the LE cap stops the rate limit
34	 * being burned, and the total cap (which also counts attempts that never reached
35	 * LE, e.g. port 80 permanently occupied) stops a customer hammering a button that
36	 * cannot possibly succeed.
37	 */
38	const ISSUE_WINDOW_MS = 7 * 86400_000;
39	const MAX_LE_ATTEMPTS_PER_WINDOW = 4;
40	const MAX_TOTAL_ATTEMPTS_PER_WINDOW = 6;
41	/** Outcomes that never reached the ACME server, so never consumed a slot. */
42	const SSL_STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
43	const SSL_STEP_SANDBOX = "simulated (sandbox)";
44	
45	type SslPayload = { certId?: string; domain?: string; renewal?: boolean };
46	
47	function payloadOf(job: { payload: unknown }): SslPayload {
48	  return (job.payload ?? {}) as SslPayload;
49	}
50	
51	async function ownedServer(serverId: string) {
52	  const user = await requireUser();
53	  const server = await db.server.findUnique({ where: { id: serverId } });
54	  if (!server) throw new Error("Not found");
55	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
56	  return { user, server };
57	}
58	
59	async function ownedCertificate(id: string) {
60	  const user = await requireUser();
61	  const cert = await db.sslCertificate.findUnique({ where: { id } });
62	  if (!cert) throw new Error("Not found");
63	  if (cert.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
64	  return { user, cert };
65	}
66	
67	/**
68	 * Issue attempts against `domain` inside the current rate-limit window.
69	 *
70	 * Keyed on the hostname, not the certificate id: LE's duplicate-certificate
71	 * limit is per identical hostname set, and deleting a row and requesting it
72	 * again mints a fresh certId. A per-row counter would reset on every
73	 * delete/re-request, which is exactly how a customer chasing a broken
74	 * certificate could burn all five weekly slots in a couple of minutes.
75	 */
76	async function issueAttemptsFor(domain: string): Promise<{
77	  total: number;
78	  leRelevant: number;
79	  resumesAt: Date | null;
80	}> {
81	  const since = new Date(Date.now() - ISSUE_WINDOW_MS);
82	  const jobs = await db.job.findMany({
83	    where: { type: "SSL_ISSUE", createdAt: { gt: since } },
84	    select: { payload: true, step: true, createdAt: true },
85	    orderBy: { createdAt: "asc" },
86	  });
87	  let total = 0;
88	  let leRelevant = 0;
89	  let oldest: Date | null = null;
90	  for (const j of jobs) {
91	    if (payloadOf(j).domain !== domain) continue;
92	    total++;
93	    // `step === null` means in flight (or a pre-2026-07-26 job): count it against
94	    // the limit. When in doubt we protect the limit, not the convenience.
95	    if (j.step !== SSL_STEP_PREFLIGHT_FAILED && j.step !== SSL_STEP_SANDBOX) leRelevant++;
96	    if (!oldest) oldest = j.createdAt;
97	  }
98	  return {
99	    total,
100	    leRelevant,
101	    resumesAt: oldest ? new Date(oldest.getTime() + ISSUE_WINDOW_MS) : null,
102	  };
103	}
104	
105	/** True when this hostname has used up its allowance for the current window. */
106	function rateLimited(rate: { total: number; leRelevant: number }): boolean {
107	  return (
108	    rate.leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW || rate.total >= MAX_TOTAL_ATTEMPTS_PER_WINDOW
109	  );
110	}
111	
112	function rateLimitMessage(
113	  domain: string,
114	  rate: { total: number; leRelevant: number; resumesAt: Date | null }
115	): string {
116	  const when = rate.resumesAt
117	    ? `${rate.resumesAt.toISOString().slice(0, 16).replace("T", " ")} UTC`
118	    : "later this week";
119	  if (rate.leRelevant >= MAX_LE_ATTEMPTS_PER_WINDOW) {
120	    return (
121	      `${rate.leRelevant} certificate requests for ${domain} have already reached Let's Encrypt in the ` +
122	      `last 7 days. Let's Encrypt allows only 5 identical certificates per week, and going over would ` +
123	      `block new certificates for this domain for a full week — so we stop one short. You can try again ` +
124	      `after ${when}.`
125	    );
126	  }
127	  return (
128	    `${rate.total} attempts for ${domain} have failed in the last 7 days before ever reaching Let's ` +
129	    `Encrypt, so another attempt would fail the same way. Fix the error shown on the certificate first; ` +
130	    `you can try again after ${when}.`
131	  );
132	}
133	
134	/** Live (queued or running) SSL_ISSUE job for a certificate, if any. */
135	async function liveIssueJob(certId: string) {
136	  const jobs = await db.job.findMany({
137	    where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
138	    select: { id: true, status: true, createdAt: true, payload: true },
139	    orderBy: { createdAt: "asc" },
140	  });
141	  return jobs.find((j) => payloadOf(j).certId === certId) ?? null;
142	}
143	
144	/** All of the current user's SSL certificates, newest first. */
145	export async function listCertificates(): Promise<SslCertificate[]> {
146	  const user = await requireUser();
147	  return db.sslCertificate.findMany({
148	    where: { userId: user.id },
149	    orderBy: { createdAt: "desc" },
150	  });
151	}
152	
153	/**
154	 * Request a one-click Let's Encrypt certificate for `domain` on one of the
155	 * caller's servers. Validates the domain, checks server ownership, applies the
156	 * shared rate-limit guard, creates a PENDING SslCertificate row and enqueues an
157	 * SSL_ISSUE job.
158	 */
159	export async function requestCertificate(
160	  serverId: string,
161	  domain: string
162	): Promise<{ error?: string; id?: string }> {
163	  let ctx;
164	  try {
165	    ctx = await ownedServer(serverId);
166	  } catch (e: any) {
167	    return { error: e.message };
168	  }
169	  const { user, server } = ctx;
170	
171	  const clean = String(domain ?? "").toLowerCase().trim().replace(/\.$/, "");
172	  if (!FQDN_RE.test(clean)) {
173	    return { error: "Enter a valid domain name (e.g. app.example.com) — no protocol, port or wildcard." };
174	  }
175	
176	  // One active/in-flight cert per (user, domain): don't let a customer stack
177	  // duplicate issue jobs for the same hostname.
178	  const existing = await db.sslCertificate.findFirst({
179	    where: { userId: user.id, domain: clean, status: { in: ["PENDING", "ISSUING", "ACTIVE"] } },
180	  });
181	  if (existing) {
182	    return {
183	      error:
184	        existing.status === "ACTIVE"
185	          ? `You already have an active certificate for ${clean}.`
186	          : `A certificate for ${clean} is already being issued.`,
187	    };
188	  }
189	
190	  // The duplicate check above is defeated by delete-and-retry, so the weekly
191	  // rate-limit guard is the thing that actually stops a retry loop from burning
192	  // Let's Encrypt's limit.
193	  const rate = await issueAttemptsFor(clean);
194	  if (rateLimited(rate)) return { error: rateLimitMessage(clean, rate) };
195	
196	  const cert = await db.sslCertificate.create({
197	    data: {
198	      userId: user.id,
199	      serverId: server.id,
200	      domain: clean,
201	      status: "PENDING",
202	      issuer: "letsencrypt",
203	    },
204	  });
205	  await db.job.create({
206	    // `domain` is carried in the payload because the rate-limit counter above
207	    // keys on the hostname and must survive the certificate row being deleted.
208	    data: { type: "SSL_ISSUE", serverId: server.id, payload: { certId: cert.id, domain: clean } },
209	  });
210	  await db.auditLog.create({
211	    data: { userId: user.id, action: "ssl.request", detail: `${clean} on ${server.hostname}` },
212	  });
213	  revalidatePath("/dashboard/ssl");
214	  return { id: cert.id };
215	}
216	
217	/**
218	 * Reissue a certificate now (owner only), for an ACTIVE/EXPIRED/FAILED row.
219	 *
220	 * Shares the weekly counter with requestCertificate and the worker's renewal
221	 * sweep, so a customer hammering this button cannot exhaust Let's Encrypt's
222	 * duplicate-certificate limit.
223	 */
224	export async function renewCertificate(id: string): Promise<{ error?: string }> {
225	  let ctx;
226	  try {
227	    ctx = await ownedCertificate(id);
228	  } catch (e: any) {
229	    return { error: e.message };
230	  }
231	  const { user, cert } = ctx;
232	
233	  if (!["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status)) {
234	    return { error: "This certificate is already being worked on — wait for the current attempt to finish." };
235	  }
236	  if (!cert.serverId) {
237	    return { error: "This certificate is not attached to a server, so it cannot be issued." };
238	  }
239	  if (await liveIssueJob(cert.id)) {
240	    return { error: "An issue job for this certificate is already queued." };
241	  }
242	
243	  const rate = await issueAttemptsFor(cert.domain);
244	  if (rateLimited(rate)) return { error: rateLimitMessage(cert.domain, rate) };
245	
246	  // One in-flight job per server, matching the worker's own invariant.
247	  const busy = await db.job.count({
248	    where: { serverId: cert.serverId, status: { in: ["QUEUED", "RUNNING"] } },
249	  });
250	  if (busy > 0) {
251	    return {
252	      error:
253	        "Another operation is already queued for this server. The platform runs one job at a time — try again once it finishes.",
254	    };
255	  }
256	
257	  await db.job.create({
258	    data: {
259	      type: "SSL_ISSUE",
260	      serverId: cert.serverId,
261	      // `renewal: true` keeps a still-valid certificate ACTIVE if the reissue
262	      // fails, instead of flipping a working site's row to FAILED.
263	      payload: { certId: cert.id, domain: cert.domain, renewal: true },
264	    },
265	  });
266	  await db.auditLog.create({
267	    data: { userId: user.id, action: "ssl.renew", detail: `${cert.domain}` },
268	  });
269	  revalidatePath("/dashboard/ssl");
270	  return {};
271	}
272	
273	/**
274	 * Permanently remove a certificate record (owner only).
275	 *
276	 * ISSUING is only protected while a job is genuinely running. Before
277	 * 2026-07-26 this refused every ISSUING row unconditionally, so a row stranded
278	 * by a worker restart was permanently undeletable — and because
279	 * requestCertificate rejects a new request while a PENDING/ISSUING/ACTIVE row
280	 * exists for the hostname, the customer lost the ability to get a certificate
281	 * for that domain at all, with no way to clear it themselves.
282	 */
283	export async function deleteCertificate(id: string): Promise<{ error?: string }> {
284	  let ctx;
285	  try {
286	    ctx = await ownedCertificate(id);
287	  } catch (e: any) {
288	    return { error: e.message };
289	  }
290	  const { user, cert } = ctx;
291	
292	  if (cert.status === "PENDING" || cert.status === "ISSUING") {
293	    const live = await liveIssueJob(cert.id);
294	    if (live?.status === "RUNNING") {
295	      return {
296	        error:
297	          "certbot is running for this domain right now — deleting mid-issue would leave a certificate on the " +
298	          "server with no record of it. Try again in a minute.",
299	      };
300	    }
301	    if (live) {
302	      // Queued but not started: cancel it, otherwise the worker would pick up a
303	      // job whose certificate row no longer exists and log a spurious failure.
304	      await db.job.updateMany({
305	        where: { id: live.id, status: "QUEUED" },
306	        data: {
307	          status: "FAILED",
308	          error: "Cancelled — the customer deleted the certificate request before it started.",
309	        },
310	      });
311	    }
312	  }
313	
314	  await db.sslCertificate.delete({ where: { id } });
315	  await db.auditLog.create({
316	    data: { userId: user.id, action: "ssl.delete", detail: `${cert.domain}` },
317	  });
318	  revalidatePath("/dashboard/ssl");
319	  return {};
320	}
321	
322	/**
323	 * Flip automatic renewal on/off for a certificate (owner only).
324	 *
325	 * This is no longer decoration: worker/ssl.ts's renewal sweep reads `autoRenew`
326	 * and, when it is off, reissues nothing and warns the customer before expiry
327	 * instead.
328	 */
329	export async function toggleAutoRenew(id: string): Promise<{ error?: string }> {
330	  let ctx;
331	  try {
332	    ctx = await ownedCertificate(id);
333	  } catch (e: any) {
334	    return { error: e.message };
335	  }
336	  await db.sslCertificate.update({
337	    where: { id },
338	    data: { autoRenew: !ctx.cert.autoRenew },
339	  });
340	  await db.auditLog.create({
341	    data: {
342	      userId: ctx.user.id,
343	      action: "ssl.autorenew",
344	      detail: `${ctx.cert.domain} -> ${!ctx.cert.autoRenew ? "on" : "off"}`,
345	    },
346	  });
347	  revalidatePath("/dashboard/ssl");
348	  return {};
349	}
