1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { connectionTarget, serverRootPassword, type SftpServer } from "../lib/sftp";
4	import { Client as SshClient } from "ssh2";
5	import { connect as tlsConnect } from "node:tls";
6	import type { Job, SslCertificate } from "@prisma/client";
7	
8	/**
9	 * SSL certificate lifecycle: issuance (SSL_ISSUE), renewal, and reconciliation.
10	 *
11	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
12	 *   SSL_ISSUE: sslIssue,
13	 * and put the lifecycle sweep on the loop's timer (same shape as
14	 * `lastBackupSweep` / `scheduledBackupSweep`):
15	 *   import { sslIssue, sslSweep } from "./ssl";
16	 *   let lastSslSweep = 0;
17	 *   if (Date.now() - lastSslSweep > 30 * 60_000) {
18	 *     lastSslSweep = Date.now();
19	 *     try { await sslSweep(); } catch (e) { console.error("[ssl] sweep error", e); }
20	 *   }
21	 *
22	 * Until 2026-07-26 `sslIssue` was the ONLY thing in this file. Certificates were
23	 * issued once and then never looked at again, so:
24	 *   - every certificate silently died at 90 days while the dashboard kept a green
25	 *     pulsing ACTIVE dot beside a neutral "Expires" date (EXPIRED was documented
26	 *     in the schema and written by nothing);
27	 *   - a row could sit in ISSUING forever if the worker was restarted mid-issue,
28	 *     and the customer could not even delete it;
29	 *   - `expiresAt` could be a computed now+90d guess rather than an observed date.
30	 * `sslSweep` fixes all three, and `verifyServed` reads back what is actually
31	 * being served so "active" means a certificate we have really seen.
32	 *
33	 * SAFETY: actually issuing a Let's Encrypt cert means SSHing to the customer's
34	 * VM and running certbot against a live, DNS-pointed domain. The real path runs
35	 * only when we're NOT in SANDBOX and ENABLE_REAL_SSL === "1"; in SANDBOX the
36	 * handler simulates, and outside SANDBOX without the flag it FAILS LOUDLY rather
37	 * than claiming a certificate that does not exist.
38	 */
39	
40	/**
41	 * A Let's Encrypt certificate is valid for 90 days. Used ONLY by the SANDBOX
42	 * simulation below, which labels itself as such. The real path must never
43	 * compute an expiry — see readObservedExpiry().
44	 */
45	const SANDBOX_CERT_LIFETIME_MS = 90 * 86400_000;
46	
47	/**
48	 * ACME account / contact email passed to certbot (`-m`). Let's Encrypt uses it
49	 * for expiry warnings. Override with CERTBOT_EMAIL; falls back to a constant.
50	 */
51	const CERTBOT_EMAIL = process.env.CERTBOT_EMAIL || "ssl-admin@nxeon.local";
52	
53	/** Overall SSH connect timeout, and per-certbot-command timeout. */
54	const SSH_CONNECT_TIMEOUT_MS = 15_000;
55	const CERTBOT_TIMEOUT_MS = 120_000;
56	/** Shorter budget for the quick pre-flight/install probes. */
57	const PROBE_TIMEOUT_MS = 60_000;
58	
59	// ---------------------------------------------------------------------------
60	// Lifecycle tuning
61	// ---------------------------------------------------------------------------
62	
63	/**
64	 * Renew when 21 days or less remain. Two hard constraints pin this number:
65	 *  - certbot only renews a lineage when fewer than 30 days remain. Asking
66	 *    earlier is a no-op ("Certificate not yet due for renewal"), so a 30-day
67	 *    lead would SSH into the customer's VM every sweep and achieve nothing.
68	 *  - the retry ladder below spends up to ~4.25 days inside one rate-limit
69	 *    window, so we need several windows of runway before the cert actually dies.
70	 * 21 days sits inside certbot's own window and still leaves three weeks of slack.
71	 */
72	const RENEW_LEAD_MS = 21 * 86400_000;
73	
74	/**
75	 * Rolling window and hard caps for issue attempts against ONE hostname.
76	 *
77	 * `MAX_LE_ATTEMPTS_PER_WINDOW` protects Let's Encrypt's limit of 5 duplicate
78	 * certificates (identical hostname set) per week. Exceeding it locks the customer
79	 * out of HTTPS for a full week — far worse than renewing a day late — so we stop
80	 * at 4 and leave one slot for the customer's own manual "Renew now".
81	 *
82	 * `MAX_TOTAL_ATTEMPTS_PER_WINDOW` counts attempts that never reached Let's
83	 * Encrypt as well. Those cost no rate-limit slot, but they are the ones that
84	 * repeat forever (port 80 permanently occupied, certbot uninstallable), and
85	 * without a cap the sweep would SSH into the customer's VM to fail identically
86	 * every 30 minutes indefinitely.
87	 */
88	const ISSUE_WINDOW_MS = 7 * 86400_000;
89	const MAX_LE_ATTEMPTS_PER_WINDOW = 4;
90	const MAX_TOTAL_ATTEMPTS_PER_WINDOW = 6;
91	
92	/**
93	 * Wait required before the next attempt, indexed by how many attempts of ANY
94	 * kind have already been made for this hostname inside the current window: the
95	 * first is immediate, then 6h / 24h / 72h (the last value repeats).
96	 *
97	 * Indexing on the total — not just the rate-limit-relevant ones — is what makes
98	 * the sweep incapable of looping. A locally-failing attempt does not consume a
99	 * Let's Encrypt slot, so if backoff were keyed on the LE counter a permanently
100	 * broken server would be retried on every single sweep pass forever. Keyed on the
101	 * total, the ladder allows at most ~4 attempts per hostname per week (0h, 6h,
102	 * 30h, 102h, 174h > one window) however often the sweep runs.
103	 */
104	const RENEW_BACKOFF_MS = [0, 6 * 3600_000, 24 * 3600_000, 72 * 3600_000];
105	
106	/**
107	 * How long a PENDING row may sit with no SSL_ISSUE job at all before we call it
108	 * lost. A row that IS attached to a queued job is never aged out no matter how
109	 * long it waits — the queue is serial platform-wide and a genuine 40-minute wait
110	 * behind a MIGRATE is not a failure (the dashboard explains the wait instead).
111	 */
112	const ORPHAN_PENDING_MS = 15 * 60_000;
113	
114	/**
115	 * Grace after a terminal SSL_ISSUE job before we declare an ISSUING row orphaned.
116	 * Guards the tiny window between the handler returning and index.ts writing DONE.
117	 */
118	const ORPHAN_GRACE_MS = 2 * 60_000;
119	
120	/** TLS read-back of the certificate actually being served on :443. */
121	const TLS_PROBE_TIMEOUT_MS = 5_000;
122	
123	/**
124	 * Sweeps run INLINE in the worker's strictly serial `for(;;)` loop, so every
125	 * second spent here is a second no customer job runs. These caps keep a sweep
126	 * bounded well under a minute even with a large certificate table — the whole
127	 * point of P1-38/P1-1 is that a slow sweep is itself an outage.
128	 */
129	const MAX_CERTS_PER_SWEEP = 60;
130	const PROBE_BUDGET_MS = 25_000;
131	
132	/**
133	 * `Job.step` doubles as the machine-readable outcome of an SSL_ISSUE attempt.
134	 * We need it because the rate-limit counter must distinguish attempts that
135	 * really reached Let's Encrypt from ones that died locally (certbot missing,
136	 * port 80 busy, SSH refused). Without the distinction, a customer whose port 80
137	 * is occupied would be locked out for a week by failures LE never even saw.
138	 *
139	 * NOTE: the two "did not reach LE" values are duplicated in lib/actions-ssl.ts
140	 * (which cannot import this module — it would pull ssh2 into the Next bundle).
141	 * Keep them in sync.
142	 */
143	export const SSL_STEP_ISSUED = "certificate issued";
144	export const SSL_STEP_ACME_FAILED = "failed at the certbot/ACME step";
145	export const SSL_STEP_PREFLIGHT_FAILED = "failed before contacting Let's Encrypt";
146	export const SSL_STEP_SANDBOX = "simulated (sandbox)";
147	
148	/** Stable prefix so a repeated sweep can recognise its own pause note. */
149	const RENEWAL_PAUSED_PREFIX = "Automatic renewal is paused";
150	
151	async function notify(userId: string, title: string, body?: string, href?: string) {
152	  try {
153	    await db.notification.create({ data: { userId, title, body, href } });
154	  } catch (e) {
155	    console.error("[ssl] notify failed", e);
156	  }
157	}
158	
159	/**
160	 * Send `title` at most once per `withinMs` for this user. The sweep runs every
161	 * 30 minutes; without this a customer with one un-renewable certificate would
162	 * collect ~50 identical notifications a day and stop reading any of them.
163	 */
164	async function notifyOnce(
165	  userId: string,
166	  title: string,
167	  body: string,
168	  withinMs: number
169	): Promise<void> {
170	  const recent = await db.notification.findFirst({
171	    where: { userId, title, createdAt: { gt: new Date(Date.now() - withinMs) } },
172	    select: { id: true },
173	  });
174	  if (recent) return;
175	  await notify(userId, title, body, "/dashboard/ssl");
176	}
177	
178	// ----------------------------------------------------------------------------
179	// Real issuance path (SSH + certbot). Only reachable when
180	// `!SANDBOX && ENABLE_REAL_SSL === "1"` — see the guard in sslIssue().
181	// ----------------------------------------------------------------------------
182	
183	type SshResult = { code: number | null; stdout: string; stderr: string };
184	
185	/**
186	 * Tracks whether an attempt got as far as invoking certbot. Passed in by
187	 * reference so the value survives the throw that unwinds out of the SSH block —
188	 * the rate-limit counter needs it (see SSL_STEP_* above).
189	 */
190	type IssuePhase = { reachedAcme: boolean };
191	
192	/**
193	 * Single-quote a value for safe interpolation into a POSIX shell command.
194	 * We already restrict the domain to a strict charset below, but everything that
195	 * reaches a remote shell is quoted defensively regardless.
196	 */
197	function shellQuote(s: string): string {
198	  return `'${s.replace(/'/g, `'\\''`)}'`;
199	}
200	
201	/** Domains must look like real hostnames before we hand them to certbot. */
202	function assertSafeDomain(domain: string): void {
203	  if (!/^(?=.{1,253}$)([a-zA-Z0-9-]{1,63}\.)+[a-zA-Z]{2,63}$/.test(domain)) {
204	    throw new Error(`Refusing to issue for an unexpected domain: ${domain}`);
205	  }
206	}
