208	/**
209	 * Run one command on an already-connected ssh2 client, capturing stdout/stderr
210	 * and the exit code. Rejects on transport error or if the command exceeds
211	 * `timeoutMs` (the channel is torn down so a hung certbot can't wedge the worker).
212	 */
213	function sshExec(conn: SshClient, command: string, timeoutMs: number): Promise<SshResult> {
214	  return new Promise((resolve, reject) => {
215	    conn.exec(command, (err, stream) => {
216	      if (err) return reject(err);
217	      let stdout = "";
218	      let stderr = "";
219	      let settled = false;
220	      const timer = setTimeout(() => {
221	        if (settled) return;
222	        settled = true;
223	        try {
224	          stream.close();
225	        } catch {
226	          /* best effort */
227	        }
228	        reject(new Error(`Command timed out after ${Math.round(timeoutMs / 1000)}s`));
229	      }, timeoutMs);
230	
231	      stream
232	        .on("close", (code: number | null) => {
233	          if (settled) return;
234	          settled = true;
235	          clearTimeout(timer);
236	          resolve({ code, stdout, stderr });
237	        })
238	        .on("data", (d: Buffer) => {
239	          stdout += d.toString("utf8");
240	        })
241	        .stderr.on("data", (d: Buffer) => {
242	          stderr += d.toString("utf8");
243	        });
244	    });
245	  });
246	}
