248	/** Open an ssh2 connection to a server, run `fn`, and always end the connection. */
249	async function withSsh<T>(
250	  target: { host: string; port: number },
251	  password: string,
252	  fn: (conn: SshClient) => Promise<T>
253	): Promise<T> {
254	  const conn = new SshClient();
255	  await new Promise<void>((resolve, reject) => {
256	    const timer = setTimeout(() => {
257	      try {
258	        conn.end();
259	      } catch {
260	        /* best effort */
261	      }
262	      reject(new Error(`SSH connect timed out after ${Math.round(SSH_CONNECT_TIMEOUT_MS / 1000)}s`));
263	    }, SSH_CONNECT_TIMEOUT_MS);
264	    conn
265	      .on("ready", () => {
266	        clearTimeout(timer);
267	        resolve();
268	      })
269	      .on("error", (e) => {
270	        clearTimeout(timer);
271	        reject(e);
272	      })
273	      .connect({
274	        host: target.host,
275	        port: target.port,
276	        username: "root",
277	        password,
278	        readyTimeout: SSH_CONNECT_TIMEOUT_MS,
279	      });
280	  });
281	  try {
282	    return await fn(conn);
283	  } finally {
284	    try {
285	      conn.end();
286	    } catch {
287	      /* best effort */
288	    }
289	  }
290	}
