321	/**
322	 * Really issue a Let's Encrypt certificate for `cert.domain` by SSHing into the
323	 * customer's own VM (same host/port/root-password derivation as lib/sftp) and
324	 * driving certbot in --standalone mode. Throws on any failure so the caller's
325	 * catch marks the cert with the reason.
326	 *
327	 * Steps on the customer VM:
328	 *   1. Detect the package manager (apt-get / dnf) and ensure `certbot` exists,
329	 *      installing it if missing.
330	 *   2. Confirm TCP port 80 is free (standalone binds it for the HTTP-01
331	 *      challenge) — surface a clear error otherwise.
332	 *   3. certbot certonly --standalone -n --agree-tos -m <email> -d <domain>.
333	 *   4. Read the real notAfter back out of the issued fullchain (no guessing).
334	 *
335	 * Everything before step 3 sets nothing on `phase`; step 3 flips
336	 * `phase.reachedAcme` so a local pre-flight failure is not counted against the
337	 * Let's Encrypt weekly limit.
338	 */
339	async function issueRealCertificate(
340	  cert: SslCertificate,
341	  phase: IssuePhase
342	): Promise<{ issuedAt: Date; expiresAt: Date }> {
343	  const domain = cert.domain;
344	  assertSafeDomain(domain);
345	
346	  if (!cert.serverId) {
347	    throw new Error("Certificate is not attached to a server.");
348	  }
349	
350	  // Load exactly the fields connectionTarget()/SSH need (mirrors lib/sftp usage).
351	  const server = await db.server.findUnique({
352	    where: { id: cert.serverId },
353	    select: {
354	      id: true,
355	      rootPassword: true,
356	      rootPasswordEnc: true,
357	      sshPort: true,
358	      dedicatedIp: { select: { address: true } },
359	    },
360	  });
361	  if (!server) throw new Error(`Server ${cert.serverId} not found.`);
362	
363	  const target = connectionTarget(server as SftpServer);
364	  if (!target) {
365	    throw new Error("Server is not reachable yet — connection details are pending.");
366	  }
367	  const rootPassword = serverRootPassword(server);
368	  if (!rootPassword) throw new Error("Server has no root password set.");
369	
370	  const qDomain = shellQuote(domain);
371	  const qEmail = shellQuote(CERTBOT_EMAIL);
372	
373	  return withSsh(target, rootPassword, async (conn) => {
374	    // 1. Ensure certbot is present. `command -v` is portable; install only if missing.
375	    const have = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
376	    if (have.stdout.trim() !== "yes") {
377	      // Pick the installer from whichever package manager exists.
378	      const pm = await sshExec(
379	        conn,
380	        "if command -v apt-get >/dev/null 2>&1; then echo apt; " +
381	          "elif command -v dnf >/dev/null 2>&1; then echo dnf; else echo none; fi",
382	        PROBE_TIMEOUT_MS
383	      );
384	      const which = pm.stdout.trim();
385	      let installCmd: string;
386	      if (which === "apt") {
387	        installCmd = "DEBIAN_FRONTEND=noninteractive apt-get update -y && apt-get install -y certbot";
388	      } else if (which === "dnf") {
389	        installCmd = "dnf install -y certbot";
390	      } else {
391	        throw new Error("No supported package manager (apt-get/dnf) found to install certbot.");
392	      }
393	      const inst = await sshExec(conn, installCmd, CERTBOT_TIMEOUT_MS);
394	      if (inst.code !== 0) {
395	        throw new Error(`certbot install failed: ${(inst.stderr || inst.stdout).trim().slice(0, 300)}`);
396	      }
397	      // Re-check that certbot is now on PATH.
398	      const recheck = await sshExec(conn, "command -v certbot >/dev/null 2>&1 && echo yes || echo no", PROBE_TIMEOUT_MS);
399	      if (recheck.stdout.trim() !== "yes") {
400	        throw new Error("certbot still not available after install.");
401	      }
402	    }
403	
404	    // 2. Standalone needs port 80. If something is already listening, bail with a
405	    //    clear message rather than letting certbot fail cryptically. (We default to
406	    //    --standalone; --webroot would only be used if a docroot were known.)
407	    const portCheck = await sshExec(
408	      conn,
409	      "ss -ltnH 'sport = :80' 2>/dev/null | head -n1 || true",
410	      PROBE_TIMEOUT_MS
411	    );
412	    if (portCheck.stdout.trim().length > 0) {
413	      throw new Error(
414	        "Port 80 is in use by another service; free it (or configure webroot issuance) before requesting a standalone certificate."
415	      );
416	    }
417	
418	    // 3. Issue. --standalone spins up certbot's own HTTP-01 responder on :80.
419	    //    From here on the attempt may have consumed a Let's Encrypt slot.
420	    const certbotCmd =
421	      `certbot certonly --standalone -n --agree-tos -m ${qEmail} -d ${qDomain}`;
422	    phase.reachedAcme = true;
423	    const run = await sshExec(conn, certbotCmd, CERTBOT_TIMEOUT_MS);
424	    const combined = `${run.stdout}\n${run.stderr}`;
425	    // certbot exits 0 on success (including "Certificate not yet due for renewal").
426	    const succeeded =
427	      run.code === 0 &&
428	      /Congratulations|Successfully received certificate|not yet due for renewal|Certificate is saved/i.test(combined);
429	    if (!succeeded) {
430	      throw new Error(`certbot failed: ${combined.trim().slice(0, 400)}`);
431	    }
432	
433	    // 4. The expiry we persist is the one on the certificate, never a guess.
434	    const expiresAt = await readObservedExpiry(conn, domain);
435	    return { issuedAt: new Date(), expiresAt };
436	  });
437	}
