470	/**
471	 * Open a plain TLS connection to `domain:443` and read the certificate the
472	 * public internet is actually being handed.
473	 *
474	 * This is the cheap, honest half of "is it really active": certbot --standalone
475	 * OBTAINS a certificate but does not install it into nginx/apache, so
476	 * issued-and-not-served is the normal outcome, not an edge case. Reading it back
477	 * is the only way the dashboard can tell the difference — and it costs one
478	 * handshake to a public hostname, no SSH and no ACME.
479	 *
480	 * `rejectUnauthorized: false` is deliberate: an expired, self-signed or
481	 * wrong-name certificate is exactly the state the customer needs to be told
482	 * about, and refusing the handshake would throw that information away. Nothing
483	 * is ever sent over this socket.
484	 */
485	function probeServedCertificate(domain: string): Promise<ServedCert> {
486	  return new Promise((resolve) => {
487	    let settled = false;
488	    let socket: ReturnType<typeof tlsConnect> | null = null;
489	    const done = (r: ServedCert) => {
490	      if (settled) return;
491	      settled = true;
492	      try {
493	        socket?.destroy();
494	      } catch {
495	        /* best effort */
496	      }
497	      resolve(r);
498	    };
499	
500	    try {
501	      socket = tlsConnect(
502	        {
503	          host: domain,
504	          port: 443,
505	          servername: domain,
506	          rejectUnauthorized: false,
507	        },
508	        () => {
509	          try {
510	            const peer = socket!.getPeerCertificate();
511	            if (!peer || !peer.valid_to) {
512	              return done({ ok: false, reason: "the server presented no certificate" });
513	            }
514	            const notAfter = new Date(peer.valid_to);
515	            if (Number.isNaN(notAfter.getTime())) {
516	              return done({ ok: false, reason: `its expiry date was unreadable (${peer.valid_to})` });
517	            }
518	            const names: string[] = [];
519	            if (peer.subject?.CN) names.push(String(peer.subject.CN));
520	            for (const entry of String(peer.subjectaltname ?? "").split(",")) {
521	              const t = entry.trim();
522	              if (t.toLowerCase().startsWith("dns:")) names.push(t.slice(4));
523	            }
524	            done({ ok: true, notAfter, coversDomain: names.some((n) => hostMatches(n, domain)) });
525	          } catch (e: any) {
526	            done({ ok: false, reason: String(e?.message ?? e).slice(0, 140) });
527	          }
528	        }
529	      );
530	      // Idle timeout covers the connect phase too, so a black-holed host cannot
531	      // hold the serial worker loop open.
532	      socket.setTimeout(TLS_PROBE_TIMEOUT_MS, () =>
533	        done({ ok: false, reason: `port 443 did not respond within ${Math.round(TLS_PROBE_TIMEOUT_MS / 1000)}s` })
534	      );
535	      socket.on("error", (e: any) => done({ ok: false, reason: tlsErrorReason(e) }));
536	    } catch (e: any) {
537	      done({ ok: false, reason: tlsErrorReason(e) });
538	    }
539	  });
540	}
541	
542	// Deterministic warning texts. They are compared for equality below so a sweep
543	// can recognise a note it wrote itself and avoid overwriting a real error.
544	function notServedWarning(domain: string, reason: string): string {
545	  return (
546	    `The certificate exists, but nothing is serving it for https://${domain} — ${reason}. ` +
547	    `certbot obtains the certificate in standalone mode; it does not install it into your web server. ` +
548	    `Point your TLS config at /etc/letsencrypt/live/${domain}/fullchain.pem and privkey.pem, then reload it.`
549	  );
550	}
551	
552	function wrongNameWarning(domain: string): string {
553	  return (
554	    `Port 443 on ${domain} is serving a certificate issued for a different hostname, so visitors get ` +
555	    `NET::ERR_CERT_COMMON_NAME_INVALID. Check which certificate your web server is configured to use.`
556	  );
557	}
558	
559	/** Is `s` one of our own probe notes (rather than a real issuance/renewal error)? */
560	function isProbeWarning(s: string | null): boolean {
561	  if (!s) return false;
562	  return s.includes("nothing is serving it for https://") || s.includes("issued for a different hostname");
563	}
564	
565	/**
566	 * Make a row match the certificate the internet can actually see, and return the
567	 * expiry we now believe (observed if we could read one).
568	 *
569	 * This is where "honest status" is enforced: `expiresAt` becomes the observed
570	 * notAfter, an out-of-band renewal (certbot installs its own systemd timer on the
571	 * VM, so certificates do renew without us) is picked up instead of triggering a
572	 * pointless reissue, and an issued-but-not-installed certificate gets a visible
573	 * note instead of a silent green dot.
574	 */
575	async function verifyServed(cert: SslCertificate): Promise<Date | null> {
576	  const served = await probeServedCertificate(cert.domain);
577	  const now = Date.now();
578	
579	  if (served.ok && served.coversDomain) {
580	    const status = served.notAfter.getTime() > now ? "ACTIVE" : "EXPIRED";
581	    // A valid certificate on the wire is proof the row is healthy, so any stale
582	    // renewal error is cleared here rather than nagging forever.
583	    const lastError =
584	      status === "ACTIVE"
585	        ? null
586	        : `The certificate being served for ${cert.domain} expired on ${served.notAfter
587	            .toISOString()
588	            .slice(0, 10)}. Visitors see a browser security warning until a new one is installed.`;
589	    const changed =
590	      cert.status !== status ||
591	      cert.expiresAt?.getTime() !== served.notAfter.getTime() ||
592	      cert.lastError !== lastError;
593	    if (changed) {
594	      await db.sslCertificate.update({
595	        where: { id: cert.id },
596	        data: { status, expiresAt: served.notAfter, lastError },
597	      });
598	    }
599	    return served.notAfter;
600	  }
601	
602	  // Could not confirm a matching certificate on the wire. Keep the issuer-read
603	  // expiry (it is still the best observed value we have) but say so — and never
604	  // clobber a genuine renewal/issuance error with a probe note.
605	  const note = served.ok ? wrongNameWarning(cert.domain) : notServedWarning(cert.domain, served.reason);
606	  if ((cert.lastError === null || isProbeWarning(cert.lastError)) && cert.lastError !== note) {
607	    await db.sslCertificate.update({ where: { id: cert.id }, data: { lastError: note } });
608	  }
609	  return cert.expiresAt;
610	}
