808	/** Live (queued or running) SSL_ISSUE jobs, indexed by the cert they belong to. */
809	async function loadLiveIssueJobs() {
810	  const jobs = await db.job.findMany({
811	    where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
812	    select: { id: true, status: true, createdAt: true, payload: true },
813	    orderBy: { createdAt: "asc" },
814	  });
815	  const byCert = new Map<string, (typeof jobs)[number]>();
816	  for (const j of jobs) {
817	    const certId = payloadOf(j).certId;
818	    if (certId && !byCert.has(certId)) byCert.set(certId, j);
819	  }
820	  return byCert;
821	}
