823	/**
824	 * Age out rows that can no longer make progress, and write EXPIRED.
825	 *
826	 * Two real failures this prevents:
827	 *  - the worker is restarted mid-issue, `reapStuckJobs` retires the job, and the
828	 *    certificate row sits in ISSUING forever. The customer could not even delete
829	 *    it (lib/actions-ssl.ts refused to delete an ISSUING row), so the domain was
830	 *    permanently unrequestable — requestCertificate rejects duplicates while a
831	 *    PENDING/ISSUING/ACTIVE row exists.
832	 *  - a certificate passes its expiry and keeps a green pulsing ACTIVE dot while
833	 *    every visitor gets NET::ERR_CERT_DATE_INVALID. EXPIRED was documented in the
834	 *    schema and written by nothing.
835	 */
836	export async function sslReconcileSweep(): Promise<void> {
837	  const now = Date.now();
838	
839	  const inflight = await db.sslCertificate.findMany({
840	    where: { status: { in: ["PENDING", "ISSUING"] } },
841	    take: MAX_CERTS_PER_SWEEP,
842	  });
843	
844	  if (inflight.length > 0) {
845	    const live = await loadLiveIssueJobs();
846	    const terminal = await db.job.findMany({
847	      where: {
848	        type: "SSL_ISSUE",
849	        status: { in: ["DONE", "FAILED"] },
850	        createdAt: { gt: new Date(now - ISSUE_WINDOW_MS) },
851	      },
852	      select: { status: true, error: true, updatedAt: true, payload: true },
853	      orderBy: { createdAt: "desc" },
854	    });
855	
856	    let cleared = 0;
857	    for (const cert of inflight) {
858	      // A row attached to a queued/running job is NOT stalled, however long it
859	      // has waited: the worker is a single serial queue platform-wide, so a
860	      // legitimate wait behind a MIGRATE can be tens of minutes. The dashboard
861	      // explains that wait instead (see the queue position on /dashboard/ssl).
862	      if (live.has(cert.id)) continue;
863	
864	      const last = terminal.find((j) => payloadOf(j).certId === cert.id);
865	      const ageMs = now - cert.createdAt.getTime();
866	      let reason: string | null = null;
867	
868	      if (last?.status === "FAILED" && now - last.updatedAt.getTime() > ORPHAN_GRACE_MS) {
869	        reason =
870	          `Issuance stopped before it finished — the worker job failed terminally` +
871	          `${last.error ? `: ${last.error.slice(0, 200)}` : " (no error recorded)"}. ` +
872	          `No certificate was installed, so this is not active. You can delete this row and request it again.`;
873	      } else if (last?.status === "DONE" && now - last.updatedAt.getTime() > ORPHAN_GRACE_MS) {
874	        reason =
875	          `Issuance ended without recording a result — the worker was interrupted after the certbot step. ` +
876	          `We cannot confirm a certificate exists, so this is not being reported as active. Request it again.`;
877	      } else if (!last && ageMs > ORPHAN_PENDING_MS) {
878	        reason =
879	          `No issuance job ever ran for this request — it was queued ${Math.round(ageMs / 60_000)} minutes ago ` +
880	          `and never picked up. Nothing was installed. Request it again.`;
881	      }
882	
883	      if (!reason) continue;
884	      await db.sslCertificate.update({
885	        where: { id: cert.id },
886	        data: { status: "FAILED", lastError: reason.slice(0, 500) },
887	      });
888	      await notifyOnce(
889	        cert.userId,
890	        `SSL certificate request for ${cert.domain} did not complete`,
891	        reason.slice(0, 200),
892	        6 * 3600_000
893	      );
894	      cleared++;
895	    }
896	    if (cleared > 0) console.log(`[ssl] reconciled ${cleared} stalled certificate row(s)`);
897	  }
898	
899	  // Anything still flagged ACTIVE past its observed expiry is not active.
900	  const lapsed = await db.sslCertificate.findMany({
901	    where: { status: "ACTIVE", expiresAt: { lt: new Date(now) } },
902	    take: MAX_CERTS_PER_SWEEP,
903	  });
904	  for (const cert of lapsed) {
905	    await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "EXPIRED" } });
906	    await notifyOnce(
907	      cert.userId,
908	      `SSL certificate expired for ${cert.domain}`,
909	      `The certificate expired on ${cert.expiresAt!.toISOString().slice(0, 10)}. Visitors now see a browser ` +
910	        `security warning on https://${cert.domain} until a new one is issued and installed.`,
911	      24 * 3600_000
912	    );
913	  }
914	  if (lapsed.length > 0) console.log(`[ssl] marked ${lapsed.length} certificate(s) EXPIRED`);
915	}
