16	export default async function SslPage() {
17	  const user = await requireUser();
18	
19	  const [certificates, servers] = await Promise.all([
20	    db.sslCertificate.findMany({
21	      where: { userId: user.id },
22	      orderBy: { createdAt: "desc" },
23	    }),
24	    db.server.findMany({
25	      where: { userId: user.id },
26	      orderBy: { createdAt: "desc" },
27	    }),
28	  ]);
29	
30	  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
31	  const myServerIds = new Set(servers.map((s) => s.id));
32	
33	  // ---------------------------------------------------------------------------
34	  // Queue visibility.
35	  //
36	  // The worker claims ONE job at a time platform-wide — `worker/index.ts` picks
37	  // the oldest `status: "QUEUED"` row and awaits it inside a serial `for(;;)` —
38	  // so a certificate request genuinely can sit behind another tenant's long
39	  // MIGRATE. That happened on 2026-07-26: a request read "pending" for 13
40	  // minutes with nothing on screen to distinguish a queue from a crash, so the
41	  // customer had no way to know whether to wait or retry. Resolve the real
42	  // position here (this page already polls) instead of leaving them guessing.
43	  // ---------------------------------------------------------------------------
44	  const inflight = certificates.filter((c) => c.status === "PENDING" || c.status === "ISSUING");
45	  const queueByCert = new Map<string, QueueInfo>();
46	
47	  if (inflight.length > 0) {
48	    const [sslJobs, running] = await Promise.all([
49	      db.job.findMany({
50	        where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
51	        select: { id: true, status: true, createdAt: true, payload: true },
52	        orderBy: { createdAt: "asc" },
53	      }),
54	      // Whatever is holding the single worker slot right now.
55	      db.job.findFirst({
56	        where: { status: "RUNNING" },
57	        select: { type: true, serverId: true },
58	        orderBy: { createdAt: "asc" },
59	      }),
60	    ]);
61	
62	    for (const cert of inflight) {
63	      const job = sslJobs.find((j) => ((j.payload ?? {}) as SslPayload).certId === cert.id);
64	
65	      // No queued or running job at all: the request cannot make progress. Say so
66	      // rather than spinning — the reconcile sweep will age it out, and the row is
67	      // deletable in the meantime.
68	      if (!job) {
69	        queueByCert.set(cert.id, {
70	          state: "none",
71	          position: 0,
72	          aheadCount: 0,
73	          queuedAtIso: cert.createdAt.toISOString(),
74	          blocking: null,
75	        });
76	        continue;
77	      }
78	
79	      if (job.status === "RUNNING") {
80	        queueByCert.set(cert.id, {
81	          state: "running",
82	          position: 0,
83	          aheadCount: 0,
84	          queuedAtIso: job.createdAt.toISOString(),
85	          blocking: null,
86	        });
87	        continue;
88	      }
89	
90	      // FIFO by createdAt, matching the worker's claim order exactly.
91	      const aheadCount = await db.job.count({
92	        where: { status: "QUEUED", createdAt: { lt: job.createdAt } },
93	      });
94	      queueByCert.set(cert.id, {
95	        state: "queued",
96	        position: aheadCount + 1,
97	        aheadCount,
98	        queuedAtIso: job.createdAt.toISOString(),
99	        blocking: running
100	          ? {
101	              type: running.type,
102	              // Only the job type is exposed, never whose server it is beyond
103	              // "yours or not" — enough to explain the wait, nothing more.
104	              mine: running.serverId ? myServerIds.has(running.serverId) : false,
105	            }
106	          : null,
107	      });
108	    }
109	  }
110	
111	  const rows: CertRow[] = certificates.map((c) => ({
112	    id: c.id,
113	    domain: c.domain,
114	    status: c.status,
115	    issuer: c.issuer,
116	    autoRenew: c.autoRenew,
117	    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
118	    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
119	    // The observed notAfter, or null. Nothing here is ever a computed guess.
120	    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
121	    lastError: c.lastError,
122	    queue: queueByCert.get(c.id) ?? null,
123	  }));
