125	  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
126	  const serverOptions: ServerOption[] = servers
127	    .filter((s) => s.status === "RUNNING")
128	    .map((s) => ({ id: s.id, hostname: s.hostname }));
129	
130	  const transitional = inflight.length > 0;
131	
132	  return (
133	    <div className="space-y-6">
134	      {transitional && <AutoRefresh />}
135	      <PageHeader
136	        title="SSL Certificates"
137	        sub="One-click Let's Encrypt certificates for domains pointed at your servers. Renewed automatically from 21 days before expiry."
138	      />
139	      <SslCertificates certificates={rows} servers={serverOptions} />
140	    </div>
141	  );
142	}
