220	function StatusCell({ c }: { c: CertRow }) {
221	  const left = daysUntil(c.expiresAt);
222	
223	  if (c.status === "PENDING") {
224	    return (
225	      <div>
226	        <StatusDot status="QUEUED" label={c.queue?.state === "none" ? "not started" : "queued"} />
227	        <QueueNote q={c.queue} />
228	      </div>
229	    );
230	  }
231	
232	  if (c.status === "ISSUING") {
233	    return (
234	      <div>
235	        {/* PROVISIONING, not ISSUING: `statusColors` has no ISSUING entry, so the
236	            literal status falls back to STOPPED's neutral grey and a certificate
237	            mid-issuance reads as "nothing happening". */}
238	        <StatusDot status="PROVISIONING" label="issuing" />
239	        {left !== null && left >= 0 && (
240	          <p className="mt-1 text-xs text-slate-400">
241	            Renewing. Your current certificate stays valid for {left} more day{left === 1 ? "" : "s"}.
242	          </p>
243	        )}
244	        <QueueNote q={c.queue} />
245	      </div>
246	    );
247	  }
248	
249	  if (c.status === "EXPIRED") {
250	    return (
251	      <div>
252	        <StatusDot status="FAILED" label="expired" />
253	        <p className="mt-1 text-xs text-red-400">
254	          {left !== null
255	            ? `Expired ${Math.abs(left)} day${Math.abs(left) === 1 ? "" : "s"} ago — visitors see a browser security warning.`
256	            : "Visitors see a browser security warning until a new certificate is installed."}
257	        </p>
258	      </div>
259	    );
260	  }
261	
262	  if (c.status === "ACTIVE") {
263	    // Never a plain green dot unless we have a real observed expiry in the future
264	    // and nothing has flagged a problem with the certificate.
265	    if (c.expiresAt === null) {
266	      return (
267	        <div>
268	          <StatusDot status="PENDING" label="unverified" />
269	          <p className="mt-1 text-xs text-amber-400">
270	            No expiry date has been read back from this certificate, so we cannot confirm it is valid.
271	          </p>
272	        </div>
273	      );
274	    }
275	    if (c.lastError) {
276	      return (
277	        <div>
278	          {/* Amber on purpose: the certificate exists, but the site is not
279	              necessarily serving it. Green here is the lie this page fixes. */}
280	          <StatusDot status="COMPLETED_WITH_ISSUES" label="issued — needs attention" />
281	        </div>
282	      );
283	    }
284	    return (
285	      <div className="flex flex-wrap items-center gap-2">
286	        <StatusDot status="ACTIVE" label="active" />
287	        {left !== null && (
288	          <Badge tone={left <= 7 ? "red" : left <= 21 ? "amber" : "green"}>
289	            {left} day{left === 1 ? "" : "s"} left
290	          </Badge>
291	        )}
292	      </div>
293	    );
294	  }
295	
296	  // FAILED (and anything unrecognised).
297	  return <StatusDot status={c.status} />;
298	}
